/**
 * Task-pane preferences: which rules are on, and the thresholds they use.
 *
 * These belong to the person, not the document, so they live in `localStorage`
 * and survive closing the pane. Rules are stored as a *deny* list so a check
 * added in a later version is switched on for someone who saved settings before
 * it existed.
 *
 * Storage is best-effort: a pane opened from `file://` (the mock harness) has no
 * usable `localStorage`, and that must not stop the pane from working.
 */
import { DEFAULT_DISABLED_ENTRIES } from "../core/catalog.ts";
import { paletteColor } from "../core/palette.ts";
import { CATEGORIES, DEFAULT_SETTINGS, type Category } from "../core/types.ts";
import { DEFAULT_DISABLED_RULES } from "../office/ruleCatalog.ts";

// 改名にあわせて `draft-reviewer.prefs.v2` から移した。旧キーの設定は読まない
// ＝ 保存済みの設定は一度だけ初期値に戻る。まだ配布前で利用者がいないこの時点が、
// それを払える唯一の機会だった。**以後は上げないこと** — 既定オフを増やすときは
// DEFAULTS_VERSION のほうを上げる（第 7 節の 16）。
const KEY = "document-corrector.prefs.v1";

/**
 * Bumped whenever a rule or a dictionary entry is *newly* switched off by default.
 *
 * The deny-list has a blind spot: a saved `disabledEntries` cannot contain an
 * entry that did not exist — or was still switched on — when it was saved, so a
 * newly default-off item would keep firing for everybody who has ever opened
 * 「ルール設定」. Bumping the storage key fixes that by throwing the settings away,
 * which is a heavy price for one word.
 *
 * So instead: `migrate()` folds the current defaults into the saved list once,
 * and records that it has. The cost is narrow and known — an item the user had
 * *deliberately* switched back on goes off again, and they switch it on once
 * more. Colors, thresholds and every rule they turned off themselves survive.
 */
const DEFAULTS_VERSION = 2;

/**
 * Rules that stopped being default-off, and so have to be *removed* from a
 * saved deny-list once.
 *
 * The fold in `migrate()` only pushes rules into the list. A rule that becomes
 * default-on is the mirror image: everyone who has opened 「ルール設定」 already
 * has it saved as off, so flipping the default alone would reach nobody — the
 * change would look like it had not shipped. Naming it here undoes that, once,
 * for the same version bump.
 *
 * The cost is the same as the other direction and just as narrow: somebody who
 * deliberately switched it off gets it back on and switches it off again. Keep
 * entries here only for the version that turned them on; older ones are dead
 * weight that would re-enable a rule the user has since turned off.
 */
const NEWLY_DEFAULT_ON: readonly string[] = Object.freeze([
  "greek-cjk-space", // DEFAULTS_VERSION 2
]);

/** Default color for each kind of space highlighting. */
export const DEFAULT_SPACE_COLOR = "#80DEEA";

export interface Preferences {
  /** Which generation of the shipped defaults has been folded in. */
  readonly defaultsVersion: number;
  /** Rule ids the user switched off. */
  readonly disabledRules: readonly string[];
  /** Dictionary entries switched off, keyed by `entryKey()`. */
  readonly disabledEntries: readonly string[];
  readonly maxSentenceLength: number;
  readonly bodyFont: string;
  readonly selectionOnly: boolean;
  readonly trackChanges: boolean;
  /**
   * Marker colors the user changed, by category. Only overrides are stored, so
   * a category left alone keeps following the checklist's own color even if
   * that color is corrected in a later version.
   */
  readonly markerColors: Readonly<Partial<Record<Category, string>>>;
  /** Color used for half-width spaces. */
  readonly halfSpaceColor: string;
  /** Color used for full-width spaces. */
  readonly fullSpaceColor: string;
  /*
   * 文献一覧の見え方。歯車の小窓（パネルのタイトル行）から変える。
   *
   * ここに置いてあるのは、**その場の状態ではなく好み**だから。以前は 3 つとも
   * DOM の初期値でしかなく、パネルを開き直すたびに既定へ戻っていた。毎回
   * 「Crossref を有効にする」を押し直す人が出る設定は、覚えていないほうが不親切。
   */
  /** 書誌の著者を先頭 1 名（`short`）にするか、原稿のまま全員出すか。 */
  readonly referenceAuthors: "short" | "all";
  /** Crossref に問い合わせて、題名と DOI の候補を出すか。 */
  readonly referenceCrossref: boolean;
  /** 文献カードの開き方。 */
  readonly referenceExpand: CardExpand;
  /** 畳んだカードの書誌を 1 行で切るか（`clip`）、折り返して全部見せるか。 */
  readonly referenceWrap: "clip" | "wrap";
  /** 図・表カードの開き方。文献とは別に覚える —— 数も中身も違う一覧なので、
      片方を全部開いておきたい人がもう片方でもそうしたいとは限らない。 */
  readonly figureExpand: CardExpand;
}

/**
 * カードの開き方。文献一覧と図・表一覧が同じ 3 択を持つ。
 *
 * - `one`  … 開くのは 1 枚だけ。**別のカードを押すと前のは閉じる。**
 * - `many` … 押したものは開いたまま残る。**別のカードを押しても閉じない。**
 *   閉じるのは、そのカードをもう一度押したとき。
 * - `all`  … はじめから全部開いている。
 *
 * `one` と `many` の違いは「他を押したときに閉じるか」だけで、そこが分かれ目に
 * なる。見比べたい 2 件を並べて開けるかどうかが変わる。
 */
export type CardExpand = "one" | "many" | "all";

/** 保存されていた値を 3 択に落とす。読めなければ既定の `one`。 */
export function cardExpand(value: unknown): CardExpand {
  return value === "all" || value === "many" ? value : "one";
}

export const DEFAULT_PREFERENCES: Preferences = Object.freeze({
  defaultsVersion: DEFAULTS_VERSION,
  disabledRules: DEFAULT_DISABLED_RULES,
  disabledEntries: DEFAULT_DISABLED_ENTRIES,
  maxSentenceLength: DEFAULT_SETTINGS.maxSentenceLength,
  bodyFont: "Times New Roman",
  selectionOnly: false,
  trackChanges: false,
  markerColors: Object.freeze({}) as Readonly<Partial<Record<Category, string>>>,
  halfSpaceColor: DEFAULT_SPACE_COLOR,
  fullSpaceColor: DEFAULT_SPACE_COLOR,
  referenceAuthors: "short",
  referenceCrossref: false,
  referenceExpand: "one",
  referenceWrap: "clip",
  figureExpand: "one",
});

/** The color a category's findings are painted with, override or checklist default. */
export function markerColor(prefs: Preferences, category: Category): string {
  return prefs.markerColors[category] ?? CATEGORIES[category].highlight;
}

/** Sets or clears one category's marker color, returning the updated preferences. */
export function withMarkerColor(
  prefs: Preferences,
  category: Category,
  color: string | null,
): Preferences {
  const colors = { ...prefs.markerColors };
  if (color === null) delete colors[category];
  else colors[category] = color;
  return { ...prefs, markerColors: colors };
}

/** Coerces whatever was in storage into a usable `Preferences`. */
export function normalize(raw: unknown): Preferences {
  const source = (raw ?? {}) as Partial<Record<keyof Preferences, unknown>>;
  const legacySpaceColor = (source as Record<string, unknown>).spaceColor;
  const strings = (value: unknown, fallback: readonly string[]): readonly string[] =>
    Array.isArray(value) ? value.filter((v): v is string => typeof v === "string") : fallback;
  const length = Number(source.maxSentenceLength);
  const font = typeof source.bodyFont === "string" ? source.bodyFont.trim() : "";
  const version = Number(source.defaultsVersion);

  return {
    defaultsVersion: Number.isFinite(version) ? version : 0,
    disabledRules: strings(source.disabledRules, DEFAULT_PREFERENCES.disabledRules),
    disabledEntries: strings(source.disabledEntries, DEFAULT_PREFERENCES.disabledEntries),
    maxSentenceLength:
      Number.isFinite(length) && length > 0 ? length : DEFAULT_PREFERENCES.maxSentenceLength,
    bodyFont: font.length > 0 ? font : DEFAULT_PREFERENCES.bodyFont,
    selectionOnly: source.selectionOnly === true,
    trackChanges: source.trackChanges === true,
    markerColors: markerColors(source.markerColors),
    // `spaceColor` is the setting saved by versions before half/full-width
    // spaces were independently configurable. It remains the migration fallback.
    halfSpaceColor: paletteColor(source.halfSpaceColor ?? legacySpaceColor) ?? DEFAULT_SPACE_COLOR,
    fullSpaceColor: paletteColor(source.fullSpaceColor ?? legacySpaceColor) ?? DEFAULT_SPACE_COLOR,
    referenceAuthors: source.referenceAuthors === "all" ? "all" : "short",
    referenceCrossref: source.referenceCrossref === true,
    referenceExpand: cardExpand(source.referenceExpand),
    referenceWrap: source.referenceWrap === "wrap" ? "wrap" : "clip",
    figureExpand: cardExpand(source.figureExpand),
  };
}

/** Keeps only real categories set to a color the palette actually offers. */
function markerColors(raw: unknown): Readonly<Partial<Record<Category, string>>> {
  if (raw === null || typeof raw !== "object") return DEFAULT_PREFERENCES.markerColors;
  const result: Partial<Record<Category, string>> = {};
  for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {
    if (!(key in CATEGORIES)) continue;
    const color = paletteColor(value);
    if (color !== null) result[key as Category] = color;
  }
  return result;
}

function storage(): Storage | null {
  try {
    return globalThis.localStorage ?? null;
  } catch {
    return null; // file:// or a host that blocks storage
  }
}

/**
 * Folds newly shipped defaults into settings saved before they existed.
 *
 * Union, not replace: everything the user switched off stays off, except the
 * few rules named in `NEWLY_DEFAULT_ON`, which are lifted out because a saved
 * deny-list would otherwise hide the change from everybody who has it saved.
 * See `DEFAULTS_VERSION` for why this is preferred over discarding the settings.
 */
export function migrate(prefs: Preferences): Preferences {
  if (prefs.defaultsVersion >= DEFAULTS_VERSION) return prefs;
  const turnedOn = new Set(NEWLY_DEFAULT_ON);
  return {
    ...prefs,
    defaultsVersion: DEFAULTS_VERSION,
    disabledRules: [...new Set([...prefs.disabledRules, ...DEFAULT_DISABLED_RULES])].filter(
      (id) => !turnedOn.has(id),
    ),
    disabledEntries: [...new Set([...prefs.disabledEntries, ...DEFAULT_DISABLED_ENTRIES])],
  };
}

export function loadPreferences(): Preferences {
  const store = storage();
  if (!store) return DEFAULT_PREFERENCES;
  try {
    const saved = store.getItem(KEY);
    if (saved === null) return DEFAULT_PREFERENCES;
    const migrated = migrate(normalize(JSON.parse(saved)));
    // Written back now, so the fold happens once rather than on every open —
    // otherwise switching an item back on would not survive a reload.
    savePreferences(migrated);
    return migrated;
  } catch {
    return DEFAULT_PREFERENCES;
  }
}

export function savePreferences(prefs: Preferences): void {
  const store = storage();
  if (!store) return;
  try {
    store.setItem(KEY, JSON.stringify(prefs));
  } catch {
    // Out of quota or storage disabled: settings just do not persist.
  }
}

/** Turns one rule on or off, returning the updated preferences. */
export function withRule(prefs: Preferences, ruleId: string, enabled: boolean): Preferences {
  const disabled = new Set(prefs.disabledRules);
  if (enabled) disabled.delete(ruleId);
  else disabled.add(ruleId);
  return { ...prefs, disabledRules: [...disabled] };
}

/** Turns one dictionary entry on or off, returning the updated preferences. */
export function withEntry(prefs: Preferences, key: string, enabled: boolean): Preferences {
  const disabled = new Set(prefs.disabledEntries);
  if (enabled) disabled.delete(key);
  else disabled.add(key);
  return { ...prefs, disabledEntries: [...disabled] };
}
