/* global document, HTMLElement */
/**
 * 「点検するルール」: which checks run, and which words each dictionary rule looks
 * for. One tab of the 「設定」 window (src/dialog/settings.ts), which owns the
 * window itself and calls `mountRules` once, at startup.
 *
 * This was its own window — ［ルール設定］ on the ribbon — until the two proved
 * to be the same thing behind two buttons: the same settings, the same storage,
 * and only one of them allowed open at a time.
 *
 * See src/dialog/bridge.ts for how the window exchanges settings with the pane.
 */
import { entryKey } from "../core/catalog.ts";
import { CATEGORIES, type Category } from "../core/types.ts";
import { RULE_CATALOG, type CatalogItem } from "../office/ruleCatalog.ts";
import { DEFAULT_PREFERENCES, withEntry, withRule, type Preferences } from "../taskpane/prefs.ts";
import { byId, preferences, tabs, updatePreferences } from "./bridge.ts";

/** Categories that actually have rules, in checklist order. */
const SECTIONS: readonly { category: Category; items: readonly CatalogItem[] }[] = (
  Object.keys(CATEGORIES) as Category[]
)
  .map((category) => ({ category, items: RULE_CATALOG.filter((item) => item.category === category) }))
  .filter((section) => section.items.length > 0);

/** Wires up the ルール tab. The settings window has already seeded preferences. */
export function mountRules(): void {
  byId("rule-all-on").onclick = () => setAllRules(true);
  byId("rule-all-off").onclick = () => setAllRules(false);
  byId("rule-reset").onclick = () => {
    apply({
      disabledRules: DEFAULT_PREFERENCES.disabledRules,
      disabledEntries: DEFAULT_PREFERENCES.disabledEntries,
    });
    renderRules();
  };

  renderRules();
}

function apply(patch: Partial<Preferences>): void {
  updatePreferences(patch);
  updateRuleCount();
}

function setAllRules(enabled: boolean): void {
  apply({ disabledRules: enabled ? [] : RULE_CATALOG.map((item) => item.id) });
  renderRules();
}

function ruleEnabled(ruleId: string): boolean {
  return !preferences().disabledRules.includes(ruleId);
}

function updateRuleCount(): void {
  const on = RULE_CATALOG.filter((item) => ruleEnabled(item.id)).length;
  byId("rule-count").textContent = `${RULE_CATALOG.length} 件中 ${on} 件が有効`;
  for (const { category, items } of SECTIONS) {
    const tab = document.getElementById(`tab-${category}`);
    if (tab) tab.textContent = tabLabel(category, items);
  }
}

function tabLabel(category: Category, items: readonly CatalogItem[]): string {
  const on = items.filter((item) => ruleEnabled(item.id)).length;
  return `${CATEGORIES[category].short} ${on}/${items.length}`;
}

// --- ルール一覧 ------------------------------------------------------------

/**
 * Rebuilds every tab.
 *
 * The whole set is redrawn rather than the open tab alone because 「すべて有効」
 * and 「既定に戻す」 change rules on tabs the user cannot see.
 */
function renderRules(): void {
  const panels = SECTIONS.map(({ category, items }) => {
    const body = document.createElement("div");
    body.setAttribute("role", "tabpanel");

    const info = CATEGORIES[category];
    const heading = document.createElement("p");
    heading.className = "lead";
    const swatch = document.createElement("span");
    swatch.className = "swatch";
    swatch.style.background = info.swatch;
    heading.append(swatch, document.createTextNode(`${info.label} — 外したルールは点検されません。`));
    body.appendChild(heading);

    for (const item of items) body.appendChild(ruleRow(item));
    return { id: category, label: tabLabel(category, items), body };
  });

  const container = byId("rule-panels");
  container.innerHTML = "";
  for (const panel of panels) container.appendChild(panel.body);
  tabs(byId("rule-tabs"), panels);

  updateRuleCount();
}

function ruleRow(item: CatalogItem): HTMLElement {
  const row = document.createElement("div");
  row.className = "rule";

  const label = document.createElement("label");
  label.className = "rule-head";
  const box = document.createElement("input");
  box.type = "checkbox";
  box.checked = ruleEnabled(item.id);
  box.onchange = () => {
    apply(withRule(preferences(), item.id, box.checked));
    row.classList.toggle("off", !box.checked);
  };
  const title = document.createElement("span");
  title.className = "rule-title";
  title.textContent = item.title;
  label.append(box, title);
  if (item.kind === "format") {
    const badge = document.createElement("span");
    badge.className = "badge";
    badge.textContent = "書式";
    badge.title = "文字の書式（フォント・太字・イタリック）を見るルール";
    label.appendChild(badge);
  }

  const summary = document.createElement("p");
  summary.className = "rule-summary";
  summary.textContent = item.summary;

  row.append(label, summary);

  if (item.example) {
    const example = document.createElement("p");
    example.className = "rule-example";
    example.textContent = `例: ${item.example}`;
    row.appendChild(example);
  }

  if (item.entries) row.appendChild(entryList(item));
  if (item.groups) row.appendChild(groupList(item));
  if (!box.checked) row.classList.add("off");
  return row;
}

/** The word list behind a dictionary rule, with a checkbox per entry. */
function entryList(item: CatalogItem): HTMLElement {
  const details = document.createElement("details");
  details.className = "entries";
  const summary = document.createElement("summary");
  summary.textContent = `語句リスト（${item.entries!.length} 件）`;
  details.appendChild(summary);

  for (const entry of item.entries!) {
    const key = entryKey(item.id, entry.from);
    const label = document.createElement("label");
    label.className = "entry";

    const box = document.createElement("input");
    box.type = "checkbox";
    box.checked = !preferences().disabledEntries.includes(key);
    box.onchange = () => apply(withEntry(preferences(), key, box.checked));

    const text = document.createElement("span");
    text.textContent = `${entry.from} → ${entry.to}`;

    const severity = document.createElement("span");
    severity.className = `severity severity-tag-${entry.severity}`;
    severity.textContent = entry.severity === "fix" ? "修正" : "確認";

    label.append(box, text, severity);
    if (entry.note) label.title = entry.note;
    details.appendChild(label);
  }
  return details;
}

/** 表記ゆれの組は読むだけ — 置換先は文書内の多数派で決まる。 */
function groupList(item: CatalogItem): HTMLElement {
  const details = document.createElement("details");
  details.className = "entries";
  const summary = document.createElement("summary");
  summary.textContent = `対象の組（${item.groups!.length} 組）`;
  details.appendChild(summary);
  for (const group of item.groups!) {
    const line = document.createElement("p");
    line.className = "entry";
    line.textContent = group.join(" / ");
    details.appendChild(line);
  }
  return details;
}
