/**
 * Spans whose *formatting* the Office layer has to look at.
 *
 * A rule like 「物理量を示す文字はイタリック」 has two halves: finding the characters
 * that are physical quantities (a text decision, made here) and checking whether
 * they are italic (a Word decision, made in `src/office/formatChecks.ts`). This
 * module is the first half, so the tricky pattern-matching stays testable.
 */
import { NMR_NUCLIDES, PHYSICAL_QUANTITIES } from "./dict.ts";
import { symbolKeysFor } from "./fonts.ts";
import { LABEL_END, isFigureNumber, labelRanges } from "./labels.ts";
import { matchAll } from "./text.ts";
import { LABELS, intextRefs, parseCaption } from "./rules/figure.ts";

/** A span of a paragraph plus what the checklist expects of its formatting. */
export interface Probe {
  readonly start: number;
  readonly end: number;
  readonly text: string;
  /** Why this span was picked, used to build the finding message. */
  readonly reason: string;
}

const GREEK = /[Ͱ-Ͽἀ-῿]+/gu;

/** ギリシャ文字（α，β，π など）に日本語フォントを使わない. */
export function greekProbes(text: string): Probe[] {
  return [...matchAll(GREEK, text)].map((m) => ({
    start: m.index,
    end: m.index + m[0].length,
    text: m[0],
    reason: "ギリシャ文字に日本語フォントが当たっています",
  }));
}

/**
 * ギリシャ文字は Symbol フォントの欧字で入力する（α は Symbol の「a」）.
 *
 * A run is probed whole, and only when Symbol can spell all of it: replacing
 * half a run would leave the paragraph in a state neither convention accepts.
 * Accented Greek (ά) and anything outside the font's repertoire is left alone.
 */
export function symbolGreekProbes(text: string): Probe[] {
  const probes: Probe[] = [];
  for (const m of matchAll(GREEK, text)) {
    const keys = symbolKeysFor(m[0]);
    if (keys === null) continue;
    probes.push({
      start: m.index,
      end: m.index + m[0].length,
      text: m[0],
      reason: `ギリシャ文字「${m[0]}」は Symbol フォントの「${keys}」で入力します`,
    });
  }
  return probes;
}

/**
 * 物理量を示す文字はイタリック.
 *
 * Only the "symbol = value" shape is probed. A bare "T" in running text could be
 * anything, but the T in "T = 298 K" is unambiguously a physical quantity, so
 * restricting to this pattern keeps the rule from flagging ordinary prose.
 */
const QUANTITY_ASSIGNMENT = new RegExp(
  `(?<![A-Za-z0-9])([${PHYSICAL_QUANTITIES.join("")}])(\\s*=\\s*)(?=[-−–]?\\d)`,
  "gu",
);

export function quantityProbes(text: string): Probe[] {
  return [...matchAll(QUANTITY_ASSIGNMENT, text)].map((m) => ({
    start: m.index,
    end: m.index + m[1]!.length,
    text: m[1]!,
    reason: `物理量「${m[1]}」はイタリックにします`,
  }));
}

/**
 * 核種の質量数は上付き（1H NMR → ¹H NMR）.
 *
 * Only the digits are probed — the element symbol keeps its normal size, and
 * superscripting it too would give 「¹ᴴ」.
 *
 * The nuclide has to be followed by NMR for the digits to mean a mass number at
 * all: 「13C」 in a table of contents is a compound label. Decoupling braces are
 * part of the name, so 「13C{1H} NMR」 gets both numbers — the outer one through
 * the brace-skipping lookahead, the inner one through its own pattern.
 */
const NUCLIDE_SET = new Set(NMR_NUCLIDES);
const NUCLIDE_ALT = [...NMR_NUCLIDES].sort((a, b) => b.length - a.length).join("|");
const NMR_TAIL = "[\\s\\-–]*NMR";

// Both patterns match 「数字＋元素記号」 loosely and let the code check the pair
// against the list. Folding that membership into the pattern would mean matching
// the digits twice over — once as part of the nuclide, once as the span to
// report — and the two readings fight each other.
const NMR_NUCLIDE = new RegExp(
  `(?<![A-Za-z0-9])(\\d{1,3})([A-Za-z]{1,2})(?=(?:\\s*\\{\\s*(?:${NUCLIDE_ALT})\\s*\\})?${NMR_TAIL})`,
  "gu",
);
const NMR_DECOUPLED = new RegExp(`(?<=\\{\\s*)(\\d{1,3})([A-Za-z]{1,2})(?=\\s*\\}${NMR_TAIL})`, "gu");

export function nmrNuclideProbes(text: string): Probe[] {
  const probes: Probe[] = [];
  for (const re of [NMR_NUCLIDE, NMR_DECOUPLED]) {
    for (const m of matchAll(re, text)) {
      const digits = m[1]!;
      if (!NUCLIDE_SET.has(`${digits}${m[2]}`)) continue;
      probes.push({
        start: m.index,
        end: m.index + digits.length,
        text: digits,
        reason: `核種の質量数「${digits}」は上付きにします（${digits}${m[2]} NMR）`,
      });
    }
  }
  return probes.sort((a, b) => a.start - b.start);
}

/** 図表のキャプションに入れる図表番号（Figure 1 など）は太字にする. */
export function captionNumberProbes(text: string): Probe[] {
  const caption = parseCaption(text);
  if (!caption) return [];
  return [
    {
      start: caption.headStart,
      end: caption.headEnd,
      text: caption.head,
      reason: `キャプションの図表番号「${caption.head}」は太字にします`,
    },
  ];
}

/**
 * 文中に引用する図表番号は太字にしない.
 *
 * A caption's own head is not an in-text reference, but a citation elsewhere in
 * the same paragraph still is — 「Figure 2. 条件は Figure 1 と同じ」.
 */
export function intextRefProbes(text: string): Probe[] {
  const caption = parseCaption(text);
  return intextRefs(text)
    .filter((ref) => !caption || ref.start >= caption.headEnd)
    .map((ref) => ({
      start: ref.start,
      end: ref.start + ref.text.length,
      text: ref.text,
      reason: `本文中の図表番号「${ref.text}」は太字にしません`,
    }));
}

/**
 * 引用文献の太字，斜体にする箇所は合っているか.
 *
 * Only the 「誌名 年, 巻,」 shape is probed. That shape lives in the bibliography
 * and essentially nowhere else, so the checks never wander into running text —
 * and it is the only place where "which token is the volume" is decidable
 * without understanding the citation.
 */
/**
 * The trap is 「Brown, K. Chem. Comm. 2020, 56, 789.」: a surname-first author list
 * ends in an initial that looks exactly like the first token of a journal name.
 * So a one-letter opening token is only accepted when a surname and comma do not
 * sit right in front of it — which still admits 「Brown, K. J. Am. Chem. Soc.」,
 * where the initial is 「K.」 and the journal really does start with 「J.」.
 */
const FIRST_TOKEN = "(?:[A-Z][A-Za-z]+\\.|(?<![A-Z][a-z]+,\\s{0,2})[A-Z]\\.)";
const JOURNAL_NAME = `(?:${FIRST_TOKEN}(?:\\s*[A-Z][A-Za-z]*\\.?)*|[A-Z][A-Za-z]{2,})`;
const REFERENCE_ENTRY = new RegExp(
  `(?<![A-Za-z0-9])(${JOURNAL_NAME})\\s+(\\d{4})\\s*,\\s*(\\d+)\\s*,`,
  "gu",
);

/** 図表のラベルは雑誌名ではない。「Table 2019, 141,」 のような並びを除く。 */
const NOT_A_JOURNAL = new Set(LABELS.map((label) => label.replace(".", "")));

function referenceEntries(text: string): RegExpExecArray[] {
  return [...matchAll(REFERENCE_ENTRY, text)].filter(
    (m) => !NOT_A_JOURNAL.has(m[1]!.replace(".", "")),
  );
}

/**
 * 誌名は斜体.
 *
 * The abbreviation's closing period is left out of the span. It is the one
 * character of a journal name that authors routinely leave upright — Word
 * reports a range of mixed emphasis as 「斜体ではない」, so 「Angew. Chem. Int. Ed.」
 * set in italics but for that last dot was being flagged as not italic at all.
 * The complaint was unanswerable: the name plainly *is* italic on the page, and
 * a period carries no emphasis anyone can see.
 */
export function journalNameProbes(text: string): Probe[] {
  return referenceEntries(text).map((m) => {
    const name = m[1]!.replace(/\.$/u, "");
    return {
      start: m.index,
      end: m.index + name.length,
      text: name,
      reason: `引用文献の誌名「${m[1]}」は斜体にします`,
    };
  });
}

/**
 * 還元種・酸化種の電荷は上付き（1b2– の 2–）.
 *
 * The charge is already understood elsewhere — `LABEL_END` has to know about it
 * so that 「1b2–」 is read as the dianion of **1b** rather than thrown away. This
 * probe asks the other half of the question: it is written, but is it raised?
 *
 * Only labels the document has established are probed. A bare 「2–」 after any
 * digit would catch subtraction and page ranges, and the sign is unavoidably
 * ambiguous in plain text — the label in front is what makes it a charge.
 */
export function chargeProbes(text: string, labels: ReadonlySet<string>): Probe[] {
  const probes: Probe[] = [];
  for (const label of labels) {
    const pattern = new RegExp(`(?<![A-Za-z0-9.])${label}(\\d{1,2}\\s*[–—−+])`, "gu");
    for (const m of matchAll(pattern, text)) {
      const charge = m[1]!;
      const start = m.index + label.length;
      probes.push({
        start,
        end: start + charge.length,
        text: charge,
        reason: `化合物 ${label} の電荷「${charge.trim()}」は上付きにします`,
      });
    }
  }
  return probes.sort((a, b) => a.start - b.start);
}

/**
 * 年は太字.
 *
 * The bold half of the pattern below. It was missing until 2026-07-29: when
 * 「巻は太字」 was corrected to 「巻は斜体」, the emphasis moved off the volume and
 * nothing picked it up, so a citation with no bold anywhere passed silently.
 */
export function yearProbes(text: string): Probe[] {
  return referenceEntries(text).map((m) => {
    const year = m[2]!;
    // 誌名にも数字が入りうる（J. Chem. Phys. 2 など）ので、年の位置は
    // 誌名の後ろから探す。lastIndexOf だけだと巻と取り違える場合がある。
    const start = m.index + m[0].indexOf(year, m[1]!.length);
    return {
      start,
      end: start + year.length,
      text: year,
      reason: `引用文献の年「${year}」は太字にします`,
    };
  });
}

/**
 * 巻は斜体.
 *
 * ACS style sets the citation as *J. Am. Chem. Soc.* **2019**, *141*, 1234 —
 * journal and volume italic, the year bold. The volume is the one that gets
 * mistaken for bold because it sits next to the year.
 */
export function volumeNumberProbes(text: string): Probe[] {
  return referenceEntries(text).map((m) => {
    const volume = m[3]!;
    const start = m.index + m[0].lastIndexOf(volume);
    return {
      start,
      end: start + volume.length,
      text: volume,
      reason: `引用文献の巻「${volume}」は斜体にします（太字にするのは年）`,
    };
  });
}

/**
 * 化合物番号は太字にする.
 *
 * The trailing letter of a series label (18a, 18d) is part of the number and
 * gets the same weight; bolding only the digits would leave 「**18**a」.
 */
const COMPOUND_NUMBER = /(?:compounds?|化合物)\s*(\d+[a-z]?)/giu;

export function compoundNumberProbes(
  text: string,
  labels: ReadonlySet<string> = new Set(),
): Probe[] {
  // Keyed by offset: 「化合物 1a」 matches both ways and must not report twice.
  const probes = new Map<number, Probe>();

  for (const m of matchAll(COMPOUND_NUMBER, text)) {
    const digits = m[1]!;
    const start = m.index + m[0].lastIndexOf(digits);
    probes.set(start, {
      start,
      end: start + digits.length,
      text: digits,
      reason: `化合物番号「${digits}」は太字にします`,
    });
  }

  // 「1a–f」 is one label spanning six compounds, and the emphasis is on all of
  // it — bolding just the 「1a」 leaves **1a**–f, which says something else.
  // Ranges are taken first so the plain-label pass below skips their insides.
  const covered: Array<{ start: number; end: number }> = [];
  for (const span of labelRanges(text)) {
    if (!labels.has(span.base)) continue;
    if (isFigureNumber(text, span.start)) continue;
    covered.push({ start: span.start, end: span.start + span.text.length });
    probes.set(span.start, {
      start: span.start,
      end: span.start + span.text.length,
      text: span.text,
      reason: `化合物番号「${span.text}」は太字にします`,
    });
  }
  const inRange = (start: number): boolean =>
    covered.some((span) => start >= span.start && start < span.end);

  // The labels the document as a whole has established (`compoundLabels`).
  //
  // Without these the rule saw only numbers carrying the word 化合物/compound,
  // which is one mention in a typical manuscript — 1a–f, 1c and 1b2– all went
  // unmarked even though 「化合物」一覧 listed them. The evidence for those comes
  // from the whole document, so a single paragraph cannot be asked for it.
  //
  // Labels are `\d+[a-z]`, so they carry no regex metacharacters to escape.
  for (const label of labels) {
    const pattern = new RegExp(`(?<![A-Za-z0-9.])${label}${LABEL_END}`, "gu");
    for (const m of matchAll(pattern, text)) {
      if (probes.has(m.index) || inRange(m.index)) continue;
      // 「(Figure 21a)」 is the third panel of a figure, not compound 21a, and
      // asking for it in bold is asking for the wrong thing.
      if (isFigureNumber(text, m.index)) continue;
      probes.set(m.index, {
        start: m.index,
        end: m.index + label.length,
        text: label,
        reason: `化合物番号「${label}」は太字にします`,
      });
    }
  }

  return [...probes.values()].sort((a, b) => a.start - b.start);
}
