/**
 * 本文の引用番号と、末尾の文献リストを結びつける.
 *
 * `[3]` on its own tells a reviewer nothing. What they want to know is *which
 * paper* that is, and whether the entry exists at all — a citation with no entry
 * and an entry nobody cites are both common, and both invisible until someone
 * lines the two lists up by hand.
 *
 * The bibliography is found the way a reader finds it: a heading near the end
 * that says 「参考文献」 or "References", followed by numbered paragraphs. Failing
 * that, a run of numbered paragraphs at the end of the document is taken as the
 * list, since that is what one looks like even when the heading is missing.
 *
 * 「Numbered」 covers three ways of writing it, because manuscripts use all three:
 * punctuated (「1.」「[1]」「(1)」), a bare number and a tab (「1→…」), and Word's own
 * automatic numbering, whose number is not in the paragraph text at all and has
 * to be handed in by the caller as `ListNumbers`.
 */
import { escapeRegExp, matchAll } from "./text.ts";
import { UNITS } from "./dict.ts";

export interface BibliographyEntry {
  readonly number: number;
  readonly paragraphIndex: number;
  /** The entry without its leading number, as written. */
  readonly text: string;
  /** Offset of the 「[2]」 marker within the paragraph, for jumping to it. */
  readonly start: number;
  /** That marker exactly as written, e.g. 「[2]」. */
  readonly marker: string;
}

/** 「参考文献」「References」「5. References」— the heading, on its own line. */
const HEADING = /^\s*(?:\d+[.．]?\s*)?(?:references?|bibliography|literature\s+cited|参考文献|引用文献|文\s*献)\s*[:：]?\s*$/iu;

/** 「1. …」「(1) …」— a numbered entry that owns its paragraph. */
const LEADING_NUMBER = /^\s*(?:\(\s*(\d{1,3})\s*\)|(\d{1,3})\s*[.．)]）?)\s*/u;

/**
 * 「1→…」「1 …」— a number with nothing after it but a gap.
 *
 * The commonest layout there is, and the one the strict form above cannot take:
 * the entry number is typed, a tab takes the text to a hanging indent, and no
 * punctuation is involved at all. 「1 はじめに」 is the same shape, which is why
 * this form is never read one paragraph at a time — see `looseRun`.
 */
const LOOSE_NUMBER = /^(\s*)(\d{1,3})[ \t　]+(?=\S)/u;

/** 「[1]」 — the one marker form that also appears mid-paragraph. */
const BRACKET_MARKER = /\[\s*(\d{1,3})\s*\]/gu;

/**
 * An entry names authors and a journal, so it is never shorter than this.
 * 「1. はじめに」 is a section heading and has to stay out of the list.
 */
const MIN_ENTRY_LENGTH = 8;

interface RawEntry {
  readonly number: number;
  readonly text: string;
  readonly start: number;
  readonly marker: string;
}

/**
 * The entries inside one paragraph — usually one, sometimes all of them.
 *
 * A bibliography is often typed as a single running paragraph:
 * 「[1] I. Osaka et al. J. Mater. Chem. C, 2020, 8, 14262. [2] J. Kido et al. …」.
 * Reading one entry per paragraph gets the first reference and swallows every
 * other one as part of its title, so `[n]` markers are split on wherever they
 * appear.
 *
 * The numbers have to keep climbing for a marker to start a new entry. A `[3]`
 * that appears inside an entry's own text — a citation within a title, say — is
 * a step backwards or a repeat, and is left as part of the entry it sits in.
 *
 * The 「1.」 and 「(1)」 forms are only honoured at the very start of a paragraph.
 * Mid-paragraph they are indistinguishable from a page number or a sentence
 * ending in a numeral, and splitting on those would shred every entry.
 */
export function splitEntries(text: string): RawEntry[] {
  // A marker starts an entry unless it is glued to the back of a word. Entries
  // are usually separated by 「. 」 but 「。[2]」 and 「1585.[2]」 happen too, so the
  // test is what must *not* precede it rather than what must.
  const markers = [...matchAll(BRACKET_MARKER, text)].filter(
    (m) => m.index === 0 || !/[A-Za-z0-9]/u.test(text[m.index - 1] ?? ""),
  );

  const accepted: Array<{ index: number; marker: string; number: number }> = [];
  let highest = 0;
  for (const m of markers) {
    const number = Number(m[1]);
    if (number <= highest) continue;
    accepted.push({ index: m.index, marker: m[0], number });
    highest = number;
  }

  if (accepted.length > 0) {
    const entries: RawEntry[] = [];
    accepted.forEach((marker, i) => {
      const from = marker.index + marker.marker.length;
      const to = accepted[i + 1]?.index ?? text.length;
      const body = text.slice(from, to).trim();
      if (body.length < MIN_ENTRY_LENGTH) return;
      entries.push({ number: marker.number, text: body, start: marker.index, marker: marker.marker });
    });
    return entries;
  }

  const m = LEADING_NUMBER.exec(text);
  if (!m) return [];
  const number = Number(m[1] ?? m[2]);
  const body = text.slice(m[0].length).trim();
  if (!Number.isFinite(number) || number < 1 || body.length < MIN_ENTRY_LENGTH) return [];
  return [{ number, text: body, start: 0, marker: m[0].trim() }];
}

/**
 * Word's own numbering for each paragraph, when the paragraph is an automatic
 * list. `undefined` where the paragraph carries no list number, and an empty
 * array when the caller cannot see Word at all (the tests, the engine).
 *
 * A list number is not in `paragraph.text`, so a bibliography numbered with
 * Word's 「段落番号」 button reads as unnumbered paragraphs from here. This array
 * is the only way to know otherwise, and the Office layer is the only caller
 * that can fill it in.
 */
export type ListNumbers = readonly (number | undefined)[];

/**
 * A loose entry: 「1→…」 in the text, or Word's own number in front of it.
 *
 * Returns null when the paragraph is not a candidate at all — too short to be a
 * reference, or carrying no number from either source.
 */
function looseEntry(text: string, listNumber: number | undefined): RawEntry | null {
  const m = LOOSE_NUMBER.exec(text);
  if (m) {
    const number = Number(m[2]);
    const body = text.slice(m[0].length).trim();
    if (number >= 1 && body.length >= MIN_ENTRY_LENGTH) {
      return { number, text: body, start: m[1]!.length, marker: m[2]! };
    }
    return null;
  }

  if (listNumber === undefined || listNumber < 1) return null;
  const body = text.trim();
  if (body.length < MIN_ENTRY_LENGTH) return null;
  // 番号は本文に無い（Word が描いている）。marker が空なので、この項目の番号は
  // 書き換えの対象にならない —— 自動採番は Word 自身が振り直す。
  return { number: listNumber, text: body, start: text.length - text.trimStart().length, marker: "" };
}

/** 「2019」 — a reference names a year, which a numbered procedure does not. */
const ENTRY_YEAR = /(?:19|20)\d{2}/u;

/**
 * The loose forms read as a run rather than one paragraph at a time.
 *
 * 「1 はじめに」 and 「1 B. Shan, Q. Miao, Tetrahedron Lett. 2017, 58, 1903.」 are
 * the same shape, so a single paragraph can never settle it. What settles it is
 * the run: entries numbered 1, 2, 3 … one after another, each the next number
 * up. A section heading has body text under it and so breaks the run at once.
 *
 * The run stops at the first paragraph that does not continue it, which is what
 * keeps a 謝辞 or an appendix after the list out. An entry split across two
 * paragraphs stops it too, and the entries before the split are kept.
 */
function looseRun(
  paragraphs: readonly string[],
  listNumbers: ListNumbers,
  start: number,
): BibliographyEntry[] {
  const entries: BibliographyEntry[] = [];
  let previous = 0;
  for (let i = start; i < paragraphs.length; i += 1) {
    const text = paragraphs[i]!;
    if (text.trim().length === 0) continue; // blank lines inside the list
    const entry = looseEntry(text, listNumbers[i]);
    if (!entry) {
      if (previous === 0) continue; // 見出しと最初の項目のあいだの前置き
      break;
    }
    if (previous > 0 && entry.number !== previous + 1) break;
    entries.push({ ...entry, paragraphIndex: i });
    previous = entry.number;
  }
  return entries.length >= 2 ? entries : [];
}

/**
 * The same run, found from the end of the document instead of from a heading.
 *
 * Walking backwards is what makes the numbering do the work: each paragraph has
 * to be one less than the one below it, so a 「5 分間撹拌した」 sitting above the
 * list ends the walk instead of hijacking it. A list that does not start at 1,
 * or whose entries name no years, is some other numbered list and is left alone
 * — without a 「参考文献」 heading there is nothing else to go on.
 */
function looseTailRun(paragraphs: readonly string[], listNumbers: ListNumbers): BibliographyEntry[] {
  const entries: BibliographyEntry[] = [];
  let next = 0;
  for (let i = paragraphs.length - 1; i >= 0; i -= 1) {
    const text = paragraphs[i]!;
    if (text.trim().length === 0) continue;
    const entry = looseEntry(text, listNumbers[i]);
    if (!entry) break;
    if (next > 0 && entry.number !== next - 1) break;
    entries.unshift({ ...entry, paragraphIndex: i });
    next = entry.number;
  }

  if (entries.length < 2 || entries[0]!.number !== 1) return [];
  const dated = entries.filter((entry) => ENTRY_YEAR.test(entry.text)).length;
  return dated * 2 >= entries.length ? entries : [];
}

/**
 * The bibliography, wherever it is and however it is laid out.
 *
 * With a heading, everything numbered after it counts. Without one, the tail of
 * the document is walked backwards for as long as the paragraphs keep parsing as
 * entries — two entries is enough to call it a list, and one is not, because a
 * single numbered paragraph is usually a step in a procedure.
 *
 * The punctuated forms (「1.」「[1]」「(1)」) are tried first and on their own, as
 * they always were. Only when they find nothing are the loose forms — a bare
 * number and a tab, or Word's own automatic numbering — read as a run.
 */
export function parseBibliography(
  paragraphs: readonly string[],
  listNumbers: ListNumbers = [],
): BibliographyEntry[] {
  let headingAt = -1;
  paragraphs.forEach((text, i) => {
    if (HEADING.test(text)) headingAt = i;
  });

  const from = (start: number): BibliographyEntry[] => {
    const entries: BibliographyEntry[] = [];
    for (let i = start; i < paragraphs.length; i += 1) {
      for (const entry of splitEntries(paragraphs[i]!)) entries.push({ ...entry, paragraphIndex: i });
    }
    return entries;
  };

  if (headingAt >= 0) {
    const entries = from(headingAt + 1);
    if (entries.length > 0) return entries;
    // 見出しが 「参考文献」 と言っている以上、年号までは求めない。
    const loose = looseRun(paragraphs, listNumbers, headingAt + 1);
    if (loose.length > 0) return loose;
  }

  let start = paragraphs.length;
  for (let i = paragraphs.length - 1; i >= 0; i -= 1) {
    const text = paragraphs[i]!;
    if (text.trim().length === 0) continue; // blank lines inside the list
    if (splitEntries(text).length === 0) break;
    start = i;
  }

  const entries = from(start);
  return entries.length >= 2 ? entries : looseTailRun(paragraphs, listNumbers);
}

/**
 * A one-line description of an entry, for a pane that is 380 px wide.
 *
 * The journal, year and volume are what identify a paper at a glance; the full
 * author list is what makes an entry unreadable at this width. So when the
 * 「誌名 年, 巻,」 shape is there, the line is built from it, and the first author
 * is kept as the thing people actually remember the paper by.
 */
/** 「2019, 58」 — the year and the volume, which is where the journal name stops. */
const YEAR_VOLUME = /(?:19|20)\d{2}\s*,\s*\d+/u;
const FIRST_AUTHOR = /^([A-Z][A-Za-z'’-]+(?:,\s*[A-Z]\.(?:\s*[A-Z]\.)*)?|(?:[A-Z]\.\s*)+[A-Z][A-Za-z'’-]+)/u;

/** Where an author list stops and a journal begins. */
const ET_AL = /\bet\s+al\.?\s*/iu;

/**
 * Drops a last author's initial that got swept into the journal name.
 *
 * 「Smith, J. A.; Brown, K. Chem. Commun. 2020, 56」 — the journal starts at
 * 「Chem.」, but 「K.」 sits right in front of it and looks exactly like the first
 * token of a name.
 *
 * Which it is depends on the entry's own convention, and the *first* author
 * gives that away. 「Smith, J. A.」 puts the surname first, so a lone initial
 * before the journal belongs to the last author. 「M. Ito」 puts initials first,
 * so nothing separates them from the journal — and 「J. Phys. Chem. A」 keeps its
 * J. Getting this wrong either way is a one-token error in a display line whose
 * full text is a hover away.
 */
const LEADING_INITIAL = /^[A-Z]\.\s+(?=[A-Z])/u;

/**
 * One line naming the paper: 「Osaka ら、J. Mater. Chem. C 2020, 8」.
 *
 * The journal is whatever sits between the authors and the year. Finding it by
 * pattern alone does not work — 「J. Kido et al. Adv. Mater. 2015」 is all capitals
 * and periods from end to end, so any 「capitalised words before a year」 rule
 * swallows the author too. So the authors are cut off explicitly: at 「et al.」
 * when it is there, and otherwise at the last comma or semicolon, which is where
 * the final author's name ends.
 */
export function describeEntry(entry: BibliographyEntry): string {
  const { authors, journal, year, volume } = entrySegments(entry.text);
  if (journal === "" || year === "") return entry.text;

  const author = FIRST_AUTHOR.exec(authors)?.[1] ?? "";
  const surname = author.includes(",")
    ? author.slice(0, author.indexOf(","))
    : author.split(/\s+/u).pop() ?? "";
  return `${surname ? `${surname} ら、` : ""}${journal} ${year}${volume ? `, ${volume}` : ""}`;
}

/**
 * 書誌 1 行を、著者・誌名・年・巻に割る。
 *
 * 表示（`describeEntry`）と検索の両方がこれを使う。**同じ「どこまでが著者か」を
 * 2 か所で決めると必ずずれる** —— 一覧に 「Osaka ら、J. Mater. Chem. C」 と出て
 * いるのに、誌名で 「J. Mater」 を探すと当たらない、という食い違いになる。
 *
 * 読めなかった欄は空文字。呼ぶ側は「読めなかった」と「空だった」を区別しない。
 */
export interface EntrySegments {
  readonly authors: string;
  readonly journal: string;
  readonly year: string;
  readonly volume: string;
}

export function entrySegments(text: string): EntrySegments {
  const yearVolume = YEAR_VOLUME.exec(text);
  if (!yearVolume) return { authors: text.trim(), journal: "", year: "", volume: "" };

  const [year = "", volume = ""] = yearVolume[0].split(/\s*,\s*/u);
  const author = FIRST_AUTHOR.exec(text)?.[1] ?? "";
  const surnameFirst = author.includes(",");

  const head = text.slice(0, yearVolume.index);
  const etAl = ET_AL.exec(head);
  const journalAt = etAl ? etAl.index + etAl[0].length : lastAuthorEnd(head);
  let journal = head.slice(journalAt).replace(/^[\s,;]+/u, "").replace(/[\s,;]+$/u, "");
  if (!etAl && surnameFirst) journal = journal.replace(LEADING_INITIAL, "");

  return {
    authors: head.slice(0, journalAt).replace(/[\s,;]+$/u, "").trim(),
    journal,
    year,
    volume,
  };
}

/** Index just past the last author separator, or 0 when there is none. */
function lastAuthorEnd(head: string): number {
  const at = Math.max(head.lastIndexOf(","), head.lastIndexOf(";"));
  return at < 0 ? 0 : at + 1;
}

// --- 本文の引用番号との突き合わせ ------------------------------------------

const BRACKET_CITATION = /\[\s*\d+(?:\s*[,、–—−-]\s*\d+)*\s*\]/gu;

/** True when the paragraph is inside the bibliography rather than the body. */
export function bibliographyParagraphs(entries: readonly BibliographyEntry[]): ReadonlySet<number> {
  return new Set(entries.map((entry) => entry.paragraphIndex));
}

/**
 * Citation markers in the body only.
 *
 * A bibliography entry may itself open with `[1]`, and counting that as a
 * citation would make every reference look cited exactly once even when nothing
 * in the text points at it — which is the case this whole module exists to find.
 */
export function bodyCitations(
  paragraphs: readonly string[],
  skip: ReadonlySet<number>,
): Array<{ paragraphIndex: number; start: number; text: string }> {
  const hits: Array<{ paragraphIndex: number; start: number; text: string }> = [];
  paragraphs.forEach((text, paragraphIndex) => {
    if (skip.has(paragraphIndex)) return;
    for (const m of matchAll(BRACKET_CITATION, text)) {
      hits.push({ paragraphIndex, start: m.index, text: m[0] });
    }
  });
  return hits;
}

/**
 * なぜ文献リストが見つからなかったのか、一行で.
 *
 * A pane that says 「見つかりませんでした」 and nothing else leaves the writer with
 * no move: the list is right there on the page. This says which half failed —
 * the heading, or the numbering under it — and shows the paragraph as the parser
 * saw it, tabs and all, which is the one thing a screenshot cannot show.
 *
 * Returns null when there is a bibliography, so the caller can use it as 「the
 * reason, if there is one」.
 */
export function bibliographyMiss(
  paragraphs: readonly string[],
  listNumbers: ListNumbers = [],
): string | null {
  if (parseBibliography(paragraphs, listNumbers).length > 0) return null;

  let headingAt = -1;
  paragraphs.forEach((text, i) => {
    if (HEADING.test(text)) headingAt = i;
  });
  if (headingAt < 0) return "「参考文献」「References」のような見出しが見つかりませんでした。";

  const at = paragraphs.findIndex((text, i) => i > headingAt && text.trim().length > 0);
  if (at < 0) return `「参考文献」の見出し（${headingAt + 1} 段落目）の後ろに本文がありませんでした。`;

  // タブを見えるようにする。番号が本文にあるのか、Word が描いているのかがここで分かる。
  const sample = paragraphs[at]!.slice(0, 30).replace(/\t/gu, "→");
  const listNumber = listNumbers[at];
  const numbering =
    listNumber === undefined ? "段落番号は付いていません" : `段落番号は ${listNumber} と読めています`;
  return `見出しは ${headingAt + 1} 段落目にありましたが、続く「${sample}…」を項目として読めませんでした（${numbering}）。`;
}

// --- 上付きの引用番号 ------------------------------------------------------
//
// 「である。1,2」 と 「その14件」 は文字としては同じ形で、上付きかどうかだけが
// 違う。テキストからは決められないので、ここは候補を出すところまでを受け持ち、
// 上付きかどうかは Word を見られる層（office/actions.ts）が決める。

/**
 * 「である。1,2」「performance.3–5」 — a raised number rides on the word before it.
 *
 * Requiring the run to be glued to what precedes it is what keeps this list to a
 * size worth asking Word about: 「25 °C」 and 「5 mL」 have a space in front of
 * their number and are not offered. A citation set after a space is missed, and
 * that is the trade — every candidate costs one search of the document.
 */
const RAISED_CANDIDATE = /(?<![\s\d])(\d{1,3}(?:[,、]\s?\d{1,3}|[–—−-]\d{1,3})*)(?![0-9A-Za-z])/gu;

/**
 * 「1b2–」 — a charge, not a citation.
 *
 * Word writes the charge of a reduced species as a superscript too, so the font
 * cannot tell 「the dianion of 1b」 from 「reference 2」. What can is the sign that
 * follows: a citation is never followed by a bare +/−.
 */
const CHARGE_AFTER = /^[\s]*[+＋–—−•·]/u;

/**
 * 「0.5」「7.25」 — the tail of a decimal, not a citation.
 *
 * An experimental section is made of these (yields, NMR shifts), and every one
 * of them would otherwise cost a search of the document to be told it is not
 * raised. The price is a citation set straight after a year — 「…in 2020.12」 —
 * which is not offered; a citation after any other sentence still is.
 */
const DECIMAL_BEFORE = /\d\s*[.．]$/u;

/**
 * 「7.71」 — the *head* of a decimal, which {@link DECIMAL_BEFORE} cannot see.
 *
 * The tail rule reads what comes before, so it needs the integer part to be
 * there. A paragraph that opens with a measurement — 「7.71 nA T–1 の応答」, a
 * line lifted out of a table — has nothing before its first digit, and that
 * digit was offered as a citation. A citation is never followed by a decimal
 * point and more digits.
 */
const DECIMAL_AFTER = /^[.．]\d/u;

/**
 * 単位記号のうち、共有の {@link UNITS} には入れられないもの.
 *
 * `UNITS` also drives 「10mL」→「10 mL」, so a symbol that doubles as something
 * else cannot go in it: 「2T」 is bithiophene, 「13C」 is a nuclide, and offering
 * a space in either would be wrong. Here the same symbols are safe, because the
 * only thing this list ever does is *withhold* a citation candidate —— the cost
 * of a wrong entry is one superscript citation that goes uncounted, not a
 * rewrite of somebody's manuscript.
 *
 * That asymmetry is also why the prefixed forms are spelled out. 「nA」 and 「kΩ」
 * carry exponents in a device paper and appear nowhere in `UNITS`, which only
 * ever needed the forms people glue to a number.
 */
const EXPONENT_ONLY_UNITS: readonly string[] = [
  "T", "mT", "µT", "μT", "G",
  "S", "mS", "µS", "μS", "nS",
  "C", "mC", "µC", "μC", "nC",
  "F", "mF", "µF", "μF", "nF", "pF",
  "N", "mN", "kN",
  // オームは 2 つの文字で書かれる。手で打つのはギリシャ文字の Ω (U+03A9)、
  // 記号一覧から入れると単位専用の Ω (U+2126) になる。見た目は同じ。
  "Ω", "Ω", "kΩ", "MΩ", "GΩ", "mΩ",
  "nA", "µA", "μA", "pA", "kA",
  "kV", "µV", "μV", "nV",
  "kW", "µW", "μW", "nW",
  "H", "mH", "µH", "μH", "Wb", "sr", "rad", "cd", "lm", "lx", "dB", "Da",
];

/** 「cm」「V」「nA」「kΩ」 — every symbol an exponent may sit on, longest first. */
const EXPONENT_UNIT_ALT = [...UNITS, ...EXPONENT_ONLY_UNITS]
  .sort((a, b) => b.length - a.length)
  .map(escapeRegExp)
  .join("|");

/**
 * 「V s–1」「Vs」「cm2 V–1 s」 — a run of units, however it is spaced.
 *
 * A composite unit is written every way there is: with spaces, with a middle
 * dot, with a slash, and —— the shape that started this —— with none of them at
 * all. 「0.05 V s–1」 has a unit standing on its own in front of the exponent
 * and was already left alone; 「0.05 Vs–1」 has 「s」 glued to the back of 「V」,
 * which read exactly like the 「m」 ending 「film1」 and made the exponent a
 * citation. So the run is matched as a whole rather than one symbol at a time:
 * a citation never rides on a stack of unit symbols, and a unit always does.
 *
 * **The count is capped on purpose.** 「m」 and 「mm」 are both units, so a long
 * stretch of unit letters can be cut into runs a great many ways, and an
 * unbounded `+` makes the engine try all of them before giving up. Five covers
 * 「kg m2 s–3 A–1」, which is as long as a derived SI unit gets.
 */
const UNIT_RUN = `(?:(?:${EXPONENT_UNIT_ALT})(?:\\s*[–—−-]?\\d+)?[\\s·⋅・/]*){1,5}`;

/**
 * 「0.5 cm2 V–1 s–1」「7.71 nA T–1」 — an exponent, not a citation.
 *
 * A unit's exponent is raised exactly like a citation number and sits in the
 * same place, so the font cannot separate them either. What can is the unit in
 * front: 「cm」 and 「V」 stand on their own, where the 「m」 ending 「film1」 does
 * not — hence the boundary before the run, without which every English word
 * ending in a unit letter would lose its citation.
 */
const UNIT_EXPONENT = new RegExp(`(?:^|[^A-Za-z])${UNIT_RUN}[–—−-]?$`, "u");

/**
 * 「2 × 10–3 M」「10–1 s」 — the exponent of a power of ten, not a citation.
 *
 * {@link UNIT_EXPONENT} looks for a unit in front, and a power of ten has a
 * digit there instead, so 「10–1」 walked straight through: the 「10」 is ordinary
 * text, the 「–1」 is raised, and a raised 「1」 riding on what precedes it is
 * exactly the shape of a citation. Every mantissa in the experimental section
 * was being read as 文献 [1]、[2]、[3]。
 *
 * What separates them is the digit before the minus. A citation attaches to a
 * word or a full stop —— 「である。1」「performance.3」 —— never to 「数字＋横棒」,
 * because that pair is already an arithmetic sign looking for its operand.
 * The price is a citation typed straight after a number range（「1990–2000」 の
 * 直後の上付き）, which is not offered; anywhere else it still is.
 */
const POWER_EXPONENT = /\d\s*[–—−-]$/u;

/**
 * Numbers that would be citations if they turned out to be raised.
 *
 * Ranges already written as `[1]` are left out: they are citations whatever
 * their font, `bodyCitations` has them, and offering the same span twice would
 * count one citation as two.
 */
export function raisedCitationCandidates(
  paragraphs: readonly string[],
  skip: ReadonlySet<number>,
): Array<{ paragraphIndex: number; start: number; text: string }> {
  const candidates: Array<{ paragraphIndex: number; start: number; text: string }> = [];
  paragraphs.forEach((text, paragraphIndex) => {
    if (skip.has(paragraphIndex)) return;
    const brackets = [...matchAll(BRACKET_CITATION, text)].map((m) => ({
      from: m.index,
      to: m.index + m[0].length,
    }));
    for (const m of matchAll(RAISED_CANDIDATE, text)) {
      const start = m.index;
      const end = start + m[0].length;
      if (CHARGE_AFTER.test(text.slice(end))) continue;
      if (DECIMAL_AFTER.test(text.slice(end))) continue;
      if (UNIT_EXPONENT.test(text.slice(0, start))) continue;
      if (POWER_EXPONENT.test(text.slice(0, start))) continue;
      if (DECIMAL_BEFORE.test(text.slice(0, start))) continue;
      if (brackets.some((span) => start < span.to && end > span.from)) continue;
      candidates.push({ paragraphIndex, start, text: m[0] });
    }
  });
  return candidates;
}
