/* global fetch */
/**
 * 「入っているマニフェストは古いか」を判定する.
 *
 * The add-in updates itself in two very different ways, and the difference is
 * the whole reason this file exists.
 *
 * **The code updates silently.** The JavaScript is fetched from GitHub Pages
 * every time the pane opens, so a corrected rule reaches everybody the moment it
 * is published. Nobody has to do anything, and nobody should be told anything.
 *
 * **The manifest does not.** Word takes a copy when the add-in is installed and
 * never looks at it again. So a new ribbon button, a renamed label, a changed
 * permission — none of those arrive until the user downloads the manifest again
 * and re-installs it. That is the only case worth interrupting someone for.
 *
 * The pane learns which manifest it is running under from the `?v=` on its own
 * URL (see `SourceLocation` in the manifests) and compares it against the
 * `version.json` that `tools/build.mjs` publishes alongside. Comparing manifest
 * versions rather than code versions is what keeps the banner quiet for the
 * updates that need no action.
 */

/** A manifest version: four numbers, as Office requires. */
export interface Version {
  readonly parts: readonly number[];
  readonly text: string;
}

const VERSION = /^\d+(?:\.\d+){0,3}$/u;

/**
 * Parses 「1.13.0.0」, or returns null.
 *
 * A missing or unparseable version is *not* an error the caller should shrug at:
 * it means the manifest predates this mechanism, which makes it old by
 * definition. `isOutdated` treats it that way.
 */
export function parseVersion(text: string | null | undefined): Version | null {
  const trimmed = (text ?? "").trim();
  if (!VERSION.test(trimmed)) return null;
  const parts = trimmed.split(".").map(Number);
  while (parts.length < 4) parts.push(0);
  return { parts, text: trimmed };
}

/** Negative when `a` is older than `b`, 0 when equal, positive when newer. */
export function compareVersions(a: Version, b: Version): number {
  for (let i = 0; i < 4; i += 1) {
    const difference = (a.parts[i] ?? 0) - (b.parts[i] ?? 0);
    if (difference !== 0) return difference;
  }
  return 0;
}

/**
 * True when the installed manifest should be replaced.
 *
 * `installed` missing → outdated, because every manifest that carries this
 * mechanism states its version. `latest` missing or unreadable → *not* outdated:
 * a broken `version.json` or an offline user must never produce a banner telling
 * someone to reinstall something that is probably fine.
 */
export function isOutdated(installed: string | null | undefined, latest: string | null | undefined): boolean {
  const newest = parseVersion(latest);
  if (!newest) return false;
  const current = parseVersion(installed);
  if (!current) return true;
  return compareVersions(current, newest) < 0;
}

/** What `version.json` carries. Everything but `manifestVersion` is optional. */
export interface VersionInfo {
  readonly manifestVersion: string;
  /** Where to download the new manifest — the distribution page. */
  readonly url?: string;
  /** One line on what changed, so the banner can say why it is worth doing. */
  readonly note?: string;
}

/** Reads `version.json`, tolerating anything that is not the shape expected. */
export function parseVersionInfo(raw: unknown): VersionInfo | null {
  if (raw === null || typeof raw !== "object") return null;
  const source = raw as Record<string, unknown>;
  const manifestVersion = typeof source.manifestVersion === "string" ? source.manifestVersion : "";
  if (parseVersion(manifestVersion) === null) return null;
  return {
    manifestVersion,
    ...(typeof source.url === "string" && source.url.length > 0 ? { url: source.url } : {}),
    ...(typeof source.note === "string" && source.note.length > 0 ? { note: source.note } : {}),
  };
}

/** Where `version.json` sits — beside the page that asks, whatever the host. */
const VERSION_URL = "version.json";

/**
 * Reads the published `version.json`, or null when it cannot be had.
 *
 * Every failure path is silent, and deliberately indistinguishable from 「まだ
 * 公開していない」. A user working offline, a host that blocks the fetch, a
 * malformed file — none of those are the user's problem to solve, and a window
 * that opens with an error about its own version check is worse than one that
 * simply shows the version it has.
 */
export async function fetchVersionInfo(): Promise<VersionInfo | null> {
  try {
    const response = await fetch(VERSION_URL, { cache: "no-store" });
    if (!response.ok) return null;
    return parseVersionInfo(await response.json());
  } catch {
    return null;
  }
}

/**
 * 「いま入っているのはどの版か、それは最新か」の 1 行.
 *
 * The banner above only appears when something is out of date, which leaves the
 * common case — everything is current — with no evidence at all. Somebody who
 * has just replaced the manifest cannot tell whether it took. So both 使い方 and
 * 設定 carry this line, which says the same thing whether or not there is
 * anything to do.
 *
 * `latest` unknown (offline, or `version.json` unreachable) prints the installed
 * version alone rather than guessing: claiming 「最新版です」 without having asked
 * is the one answer that would be worse than saying nothing.
 */
export function versionLine(installed: string | null | undefined, latest: string | null | undefined): string {
  const current = parseVersion(installed);
  const newest = parseVersion(latest);
  const notes: string[] = [];
  if (!current) notes.push("この仕組みより前の版");
  if (newest) notes.push(isOutdated(installed, latest) ? `最新は ${newest.text}` : "最新版です");
  const shown = current?.text ?? "不明";
  return notes.length === 0 ? `バージョン ${shown}` : `バージョン ${shown}（${notes.join("。")}）`;
}

/**
 * The manifest version this pane is running under, from its own URL.
 *
 * Word keeps the query string of `SourceLocation`, so `?v=1.13.0.0` is the
 * installed manifest talking. A pane opened without it is running under a
 * manifest from before this mechanism existed.
 */
export function installedVersion(search: string): string | null {
  const value = new URLSearchParams(search).get("v");
  return value && value.length > 0 ? value : null;
}
