/**
 * 更新の履歴。［設定］＞［更新履歴］が読むただ 1 つの出どころ.
 *
 * The pane's update notice can only ever say one thing — 「新しいバージョンが
 * あります」 plus the single line in `version.json` — because it is written by
 * whoever bumped the manifest and has to fit in a small popover. That leaves the
 * obvious question unanswered: 「前は何が変わったのか」. This file is the answer,
 * and the only place it is written down for users.
 *
 * **Kept by hand, on purpose.** The git log is in English and describes the code;
 * this describes what somebody using Word would notice. The two are not the same
 * list, and deriving one from the other would produce entries nobody can act on.
 *
 * `version` is the *manifest* version in force when the entry shipped, so several
 * entries can share one — the code updates itself, and most releases never touch
 * the manifest (see src/core/version.ts). `manifest: true` marks the ones that
 * did, which are exactly the ones that needed a re-install.
 *
 * Newest first. `tools/build.mjs` warns when the top entry's version has fallen
 * behind the manifest's <Version>.
 */

/** 一度の更新。日付が主で、版はそのとき入っていたマニフェストの版。 */
export interface Release {
  /** `2026-08-07`. Displayed as 2026年8月7日. */
  readonly date: string;
  /** The manifest version in force, e.g. `1.17.0.1`. */
  readonly version: string;
  /** True when the manifest changed and had to be installed again. */
  readonly manifest?: boolean;
  /** What changed, one user-visible thing per line. */
  readonly changes: readonly string[];
}

