/** 「2026年8月7日」. Falls back to the raw text when it is not a plain date. */
export function releaseDate(date: string): string {
  const parts = /^(\d{4})-(\d{2})-(\d{2})$/u.exec(date);
  if (!parts) return date;
  return `${Number(parts[1])}年${Number(parts[2])}月${Number(parts[3])}日`;
}
