/* global Office, document, location, HTMLElement, HTMLSelectElement */
/**
 * The 設定 window: which rules run, marker colors, thresholds, and how fixes are
 * written — one tab each.
 *
 * 「点検するルール」 is big enough to keep its own file (src/dialog/rules.ts); this
 * one owns the window and hands that tab over to `mountRules`.
 *
 * See src/dialog/bridge.ts for how the window exchanges settings with the pane.
 */
import { HIGHLIGHT_PALETTE } from "../core/palette.ts";
import { CATEGORIES, type Category } from "../core/types.ts";
import { RULE_CATALOG } from "../office/ruleCatalog.ts";
import {
  DEFAULT_PREFERENCES,
  markerColor,
  withMarkerColor,
  type Preferences,
} from "../taskpane/prefs.ts";
import { RELEASES, releaseDate, type Release } from "../core/changelog.ts";
import {
  fetchVersionInfo,
  installedVersion,
  isOutdated,
  versionLine,
  type VersionInfo,
} from "../core/version.ts";
import { byId, input, preferences, seedPreferences, send, tabs, updatePreferences } from "./bridge.ts";
import { mountRules } from "./rules.ts";

/** Categories worth showing a color for: the ones that can produce a finding. */
const CATEGORIES_IN_USE = (Object.keys(CATEGORIES) as Category[]).filter((category) =>
  RULE_CATALOG.some((item) => item.category === category),
);

Office.onReady(() => {
  seedPreferences();
  applyPrefsToInputs();

  // ルール tab first: 「何を点検するか」 is what people come here to change.
  // Its own tabs are built inside the panel, so mount it before the outer bar
  // hides it — a hidden panel measures nothing, and its sub-tabs would clip.
  mountRules();
  tabs(byId("settings-tabs"), [
    { id: "rules", label: "点検するルール", body: byId("panel-rules") },
    { id: "colors", label: "マーカーの色", body: byId("panel-colors") },
    { id: "review", label: "点検のしかた", body: byId("panel-review") },
    { id: "changelog", label: "更新履歴", body: byId("panel-changelog") },
  ]);

  for (const id of ["max-sentence", "body-font", "selection-only", "track-changes"]) {
    byId(id).onchange = readPrefsFromInputs;
  }
  byId("color-reset").onclick = () => {
    apply({ markerColors: DEFAULT_PREFERENCES.markerColors });
    renderColors();
  };
  byId("settings-done").onclick = () => send(true);

  renderChangelog();
  renderColors();
  showVersion();
});

/**
 * 「バージョン 1.16.0.1（最新版です）」 in the footer, and the same answer at the
 * top of ［更新履歴］.
 *
 * The installed version rides in on the URL, because a dialog is its own
 * runtime and cannot read the pane's variables (see openDialog). The published
 * one is fetched here rather than handed over, so this window says something
 * useful even when opened straight from the harness.
 */
function showVersion(): void {
  void (async () => {
    const installed = installedVersion(location.search);
    const info = await fetchVersionInfo();
    byId("version-line").textContent = versionLine(installed, info?.manifestVersion);
    showChangelogState(installed, info);
  })();
}

// --- 更新履歴 --------------------------------------------------------------
//
// パネル側の知らせは 1 行しか言えない（アイコンの小窓に収まる分だけ）。
// 「前は何が変わったのか」「いま入っているのはどこまでか」はここが引き受ける。

/** ［更新履歴］の頭の 1 行と、要るときだけ出るダウンロードのボタン。 */
function showChangelogState(installed: string | null, info: VersionInfo | null): void {
  const state = byId("changelog-state");
  if (!info) {
    // 配信元に届かなかった。入っている版だけは言える。
    state.textContent = versionLine(installed, null);
    return;
  }
  const behind = isOutdated(installed, info.manifestVersion);
  state.textContent = behind
    ? `お使いの版は ${installed ?? "不明"}、配布中は ${info.manifestVersion} です。マニフェストを入れ直すと、リボンも新しくなります。`
    : `お使いの版は ${info.manifestVersion} で、最新です。`;
  state.classList.toggle("behind", behind);

  const url = info.url;
  if (!behind || !url) return;
  const button = byId("changelog-download") as HTMLButtonElement;
  button.hidden = false;
  button.onclick = () => {
    // ダイアログにも Office の窓開けはあるが、ホストによっては無い。
    // そのときは住所を出して、手で開いてもらう。
    const opener = Office.context?.ui?.openBrowserWindow;
    if (typeof opener === "function") opener.call(Office.context.ui, url);
    else {
      const line = byId("changelog-url");
      line.textContent = url;
      line.hidden = false;
    }
  };
}

/** 新しい順に、日付・版・変更点。 */
function renderChangelog(): void {
  const list = byId("changelog");
  list.innerHTML = "";
  for (const release of RELEASES) list.appendChild(releaseCard(release));
}

function releaseCard(release: Release): HTMLElement {
  const card = document.createElement("section");
  card.className = "release";

  const head = document.createElement("p");
  head.className = "release-head";

  const date = document.createElement("strong");
  date.textContent = releaseDate(release.date);

  const version = document.createElement("span");
  version.className = "release-version";
  version.textContent = release.version;
  head.append(date, version);

  if (release.manifest) {
    // 入れ直しが要った回。要らない回との差が、この一覧のいちばんの読みどころ。
    const badge = document.createElement("span");
    badge.className = "release-badge";
    badge.textContent = "入れ直しが必要";
    head.appendChild(badge);
  }

  const changes = document.createElement("ul");
  changes.className = "release-changes";
  for (const change of release.changes) {
    const item = document.createElement("li");
    item.textContent = change;
    changes.appendChild(item);
  }

  card.append(head, changes);
  return card;
}

function apply(patch: Partial<Preferences>): void {
  updatePreferences(patch);
}

function applyPrefsToInputs(): void {
  const prefs = preferences();
  input("max-sentence").value = String(prefs.maxSentenceLength);
  input("body-font").value = prefs.bodyFont;
  input("selection-only").checked = prefs.selectionOnly;
  input("track-changes").checked = prefs.trackChanges;
}

function readPrefsFromInputs(): void {
  apply({
    maxSentenceLength: Number(input("max-sentence").value),
    bodyFont: input("body-font").value,
    selectionOnly: input("selection-only").checked,
    trackChanges: input("track-changes").checked,
  });
}

// --- マーカーの色 ----------------------------------------------------------

function renderColors(): void {
  const markers = byId("marker-colors");
  markers.innerHTML = "";
  for (const category of CATEGORIES_IN_USE) {
    markers.appendChild(
      colorRow(CATEGORIES[category].label, markerColor(preferences(), category), (value) => {
        // Back to null when it matches the checklist, so the category keeps
        // following the default rather than pinning today's value.
        const preset = CATEGORIES[category].highlight.toUpperCase();
        apply(withMarkerColor(preferences(), category, value === preset ? null : value));
      }),
    );
  }
}

/** One labelled color picker: a swatch, a palette dropdown, and its label. */
function colorRow(label: string, value: string, onchange: (value: string) => void): HTMLElement {
  const row = document.createElement("div");
  row.className = "color-row";

  const swatch = document.createElement("span");
  swatch.className = "swatch";
  swatch.style.background = value;

  const text = document.createElement("span");
  text.className = "color-label";
  text.textContent = label;

  const select = document.createElement("select");
  for (const color of HIGHLIGHT_PALETTE) {
    const option = document.createElement("option");
    option.value = color.value;
    option.textContent = color.label;
    option.selected = color.value === value.toUpperCase();
    select.appendChild(option);
  }
  select.onchange = () => {
    const chosen = (select as HTMLSelectElement).value;
    swatch.style.background = chosen;
    onchange(chosen);
  };

  row.append(swatch, text, select);
  return row;
}
