/**
 * フォント関係 (2. 書式上の誤り) の判定材料。
 *
 * Whether a run is in the right font can only be answered by Word, but *which*
 * font it ought to be in is a pure decision, so it lives here and stays
 * unit-testable. The Office layer reads `font.name` and asks these functions.
 */

/** Font families that carry Japanese glyphs. */
const JAPANESE_FONTS = [
  "ms mincho", "ｍｓ 明朝", "ms 明朝", "ms pmincho", "ms gothic", "ｍｓ ゴシック",
  "ms gothic", "ms pgothic", "hiragino", "ヒラギノ", "yu gothic", "游ゴシック",
  "yu mincho", "游明朝", "meiryo", "メイリオ", "noto sans jp", "noto serif jp",
  "noto sans cjk", "noto serif cjk", "biz ud", "hg", "osaka", "klee", "kozuka",
  "小塚", "源ノ角", "source han", "ipa", "sarasa", "morisawa", "a-otf",
] as const;

/** Serif (明朝系) Latin faces. */
const SERIF_FONTS = ["times new roman", "times", "garamond", "georgia", "cambria", "minion", "serif"] as const;

/** Sans (ゴシック系) Latin faces. */
const SANS_FONTS = ["helvetica", "arial", "calibri", "segoe ui", "verdana", "tahoma", "futura"] as const;

function normalize(name: string | null | undefined): string {
  if (!name) return "";
  // Word reports "Times New Roman,Bold" or "+mn-ea" style names.
  return name.split(",")[0]!.trim().toLowerCase();
}

/** True when the font is a Japanese face. */
export function isJapaneseFontName(name: string | null | undefined): boolean {
  const family = normalize(name);
  if (family.length === 0) return false;
  return JAPANESE_FONTS.some((jp) => family.includes(jp));
}

export function isSerifLatinFont(name: string | null | undefined): boolean {
  const family = normalize(name);
  return SERIF_FONTS.some((f) => family.includes(f));
}

export function isSansLatinFont(name: string | null | undefined): boolean {
  const family = normalize(name);
  return SANS_FONTS.some((f) => family.includes(f));
}

/** 明朝系 / ゴシック系 / それ以外. */
export type JapaneseFontStyle = "mincho" | "gothic" | "unknown";

export function japaneseFontStyle(name: string | null | undefined): JapaneseFontStyle {
  const family = normalize(name);
  if (!isJapaneseFontName(family)) return "unknown";
  if (/(mincho|明朝|serif|minion|kozuka mincho|小塚明朝)/u.test(family)) return "mincho";
  if (/(gothic|ゴシック|sans|meiryo|メイリオ|hiragino sans|kaku)/u.test(family)) return "gothic";
  return "unknown";
}

/**
 * 日英フォントの不一致:
 *   (日) ゴシック系フォント → (英) Helvetica または Arial
 *   (日) 明朝系フォント     → (英) Times New Roman など
 *
 * Returns `null` when the pairing is acceptable, or a description of the
 * expected Latin face when it is not.
 */
export function latinFontMismatch(
  japaneseFont: string | null | undefined,
  latinFont: string | null | undefined,
): { readonly expected: string; readonly reason: string } | null {
  const style = japaneseFontStyle(japaneseFont);
  if (style === "unknown") return null;
  if (!latinFont || normalize(latinFont).length === 0) return null;
  if (isJapaneseFontName(latinFont)) {
    return {
      expected: style === "mincho" ? "Times New Roman" : "Helvetica / Arial",
      reason: "英数字に日本語フォントが当たっています",
    };
  }
  if (style === "gothic" && !isSansLatinFont(latinFont)) {
    return { expected: "Helvetica / Arial", reason: "和文がゴシック系なので英文はサンセリフ" };
  }
  if (style === "mincho" && !isSerifLatinFont(latinFont)) {
    return { expected: "Times New Roman", reason: "和文が明朝系なので英文はセリフ" };
  }
  return null;
}

/** Latin face that goes with a Japanese face, for the "fix" button's default. */
export function preferredLatinFont(japaneseFont: string | null | undefined): string {
  return japaneseFontStyle(japaneseFont) === "gothic" ? "Arial" : "Times New Roman";
}

// --- Symbol フォントでのギリシャ文字 ---------------------------------------

export const SYMBOL_FONT = "Symbol";

/**
 * Adobe Symbol encoding: which Latin key produces which Greek letter.
 *
 * The checklist asks for Greek to be typed as a Latin letter in Symbol rather
 * than as a Unicode Greek character — α is 「a」 in Symbol, π is 「p」. The
 * pairings are the font's own, not a transliteration, which is why θ is `q` and
 * ω is `w`: they sit at those key positions.
 *
 * U+00B5 MICRO SIGN (µ) is deliberately absent. It is a unit prefix rather than
 * a Greek letter, and 10 µL is written with it in every house style.
 */
const SYMBOL_GREEK: Readonly<Record<string, string>> = Object.freeze({
  α: "a", β: "b", χ: "c", δ: "d", ε: "e", φ: "f", γ: "g", η: "h", ι: "i",
  ϕ: "j", κ: "k", λ: "l", μ: "m", ν: "n", ο: "o", π: "p", θ: "q", ρ: "r",
  σ: "s", τ: "t", υ: "u", ϖ: "v", ω: "w", ξ: "x", ψ: "y", ζ: "z",
  Α: "A", Β: "B", Χ: "C", Δ: "D", Ε: "E", Φ: "F", Γ: "G", Η: "H", Ι: "I",
  ϑ: "J", Κ: "K", Λ: "L", Μ: "M", Ν: "N", Ο: "O", Π: "P", Θ: "Q", Ρ: "R",
  Σ: "S", Τ: "T", Υ: "U", ς: "V", Ω: "W", Ξ: "X", Ψ: "Y", Ζ: "Z",
});

/** The Symbol-font key for a Greek character, or null when there is none. */
export function symbolKeyFor(greek: string): string | null {
  return SYMBOL_GREEK[greek] ?? null;
}

/** The Symbol-font keys spelling out a run of Greek, or null if any is unmapped. */
export function symbolKeysFor(greek: string): string | null {
  let keys = "";
  for (const character of greek) {
    const key = symbolKeyFor(character);
    if (key === null) return null;
    keys += key;
  }
  return keys.length > 0 ? keys : null;
}

export function isSymbolFont(name: string | null | undefined): boolean {
  return normalize(name) === "symbol";
}

/**
 * Word の標準色に日本語の名前を付ける。
 *
 * 一覧に `#C00000` とだけ出しても何色かは伝わらない。**近い色に丸めることは
 * しない** — 「赤」と書いてあるのに実際は別の赤だった、では一覧を信じられなく
 * なるので、この表にある色だけを名前で呼び、それ以外は 16 進のまま出す。
 */
const TEXT_COLORS: Readonly<Record<string, string>> = Object.freeze({
  "#000000": "黒",
  "#FFFFFF": "白",
  "#FF0000": "赤",
  "#C00000": "濃い赤",
  "#0000FF": "青",
  "#0070C0": "明るい青",
  "#002060": "濃い青",
  "#00B050": "緑",
  "#00B0F0": "水色",
  "#FFC000": "オレンジ",
  "#FFFF00": "黄",
  "#7030A0": "紫",
  "#808080": "グレー",
  "#A6A6A6": "うすいグレー",
});

/**
 * 一覧で色をまとめるときの鍵。
 *
 * Word は `#RRGGBB` を返すのが基本だが、色を指定していない文字には
 * 「Automatic」のような語を返すことがある。**どちらも捨てない** — 原稿の
 * ほとんどは色指定なしなので、そこを落とすと一覧が空同然になる。
 */
export function normalizeTextColor(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const key = value.trim().toUpperCase();
  return key.length > 0 ? key : null;
}

/** 一覧に出す色の名前。表にない色は 16 進のまま返す。 */
export function textColorLabel(value: string | null | undefined): string {
  const key = normalizeTextColor(value);
  if (key === null) return "自動";
  if (key === "AUTOMATIC" || key === "AUTO") return "自動";
  return TEXT_COLORS[key] ?? key;
}

/** 一覧に出す文字サイズ。10.5 は「10.5 pt」、11 は「11 pt」。 */
export function fontSizeLabel(size: number): string {
  return `${Number(size.toFixed(2))} pt`;
}
